        'rawContent': "---\r\ntitle: \"Liberation_of_Kalidasa\"\r\npage_id: 4137\r\nnamespace: 0\r\nnamespace_name: \"Main\"\r\nlatest_revision_id: 12194\r\nlast_updated: \"2010-04-09 15:48:07\"\r\nauthor: \"Asears\"\r\nis_redirect: false\r\ncategories:\r\n  - \"Second_Exodus_War\"\r\ntemplates:\r\n  - \"Military_Conflict\"\r\n  - \"Second_Exodus_War_Navbox\"\r\n---\r\n\r\n{{Military Conflict|\r\n|conflict=Liberation of Kalidasa\r\n|partof=Second Exodus War\r\n|image=\r\n|caption=\r\n|date=June 3rd, [[2322]]\r\n|place=[[Kalidasa]]\r\n|territory=[[Onyx Empire]]\r\n|status=[[United Mesarthrim Clans|Mesarthrim Victory]]\r\n|result=Liberation by [[United Mesarthrim Clans|UMC]].  Occupational government established until February [[2324]]\r\n|combatant1=[[Image:OnyxEmpireFlag.png|20px]] [[Onyx Empire]]\r\n|combatant2=[[Image:UnitedMesarthrimClansFlag.png|20px]] [[United Mesarthrim Clans]]\r\n|commander1=[[Image:OnyxEmpireFlag.png|20px]] General Sebastian Richmond\r\n|commander2=[[Image:UnitedMesarthrimClansFlag.png|20px]] [[Groß-Commandant]] Elias Faust\r\n|strength1=Kalidasa Home Guard\r\n|strength2='''[[Myt'herra]]'''<br/> - First Legion<br/> - Second Legion<br/> - Sixth Legion<br/>'''Occupation Force'''<br/>Beruf-Abteilung\r\n|losses1= Don't Know\r\n|losses2= Don't Know\r\n}}\r\n\r\n<br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br>\r\n<br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br>\r\n\r\n{{Second Exodus War Navbox}}\r\n\r\n[[Category:Second Exodus War]]"
